window.docContents[251].resolve({"/MoreStlc/#Type-Systems--MoreStlc___-More-on-the-Simply-Typed-Lambda-Calculus--Simple-Extensions-to-STLC--Lists":{"contents":"\n\nSyntax:\n\n       t ::=                Terms\n           | ...\n           | nil τ             ∅ list\n           | t₁ :: t₂          cons\n           | case t₁ of        case analysis\n               nil      => t₂\n               | xh::xt => t₃\n\n       v ::=                Values\n           | ...\n           | nil τ             nil value\n           | v₁ :: v₂          cons value\n\n       τ ::=                Types\n           | ...\n           | List τ            list of τs\n\n\nReduction:\n\n                                t₁ ⟶ t₁'\n                       --------------------------                    (cons₁)\n                         t₁ :: t₂ ⟶ t₁' :: t₂\n\n                                t₂ ⟶ t₂'\n                       --------------------------                    (cons₂)\n                         v₁ :: t₂ ⟶ v₁ :: t₂'\n\n                              t₁ ⟶ t₁'\n                -------------------------------------------         (listCase₁)\n                 (case t₁ of nil => t₂ | xh :: xt => t₃) ⟶\n                (case t₁' of nil => t₂ | xh :: xt => t₃)\n\n               ------------------------------------------          (listCaseNil)\n               (case nil τ₁ of nil => t₂ | xh :: xt => t₃)\n                                ⟶ t₂\n\n              -------------------------------------------         (listCaseCons)\n              (case (vh :: vt) of nil => t₂ | xh :: xt => t₃)\n                          ⟶ [xh:=vh][xt:=vt] t₃\n\n\nTyping:\n\n                        ----------------------------                    (nil)\n                        Γ ⊢ nil τ₁ ⦂ List τ₁\n\n                     Γ ⊢ t₁ ⦂ τ₁      Γ ⊢ t₂ ⦂ List τ₁\n            -------------------------------------------------           (cons)\n                         Γ ⊢ t₁ :: t₂ ⦂ List τ₁\n\n                        Γ ⊢ t₁ ⦂ List τ₁\n                        Γ ⊢ t₂ ⦂ τ₂\n                  (xh ↦ τ₁; xt ↦ List τ₁; Γ) ⊢ t₃ ⦂ τ₂\n          ----------------------------------------------------         (listCase)\n             Γ ⊢ (case t₁ of nil => t₂ | xh :: xt => t₃) ⦂ τ₂\n\n\n","context":"Type Systems\u0009MoreStlc: More on the Simply Typed Lambda-Calculus\u0009Simple Extensions to STLC","header":"7.1.5. Lists","id":"/MoreStlc/#Type-Systems--MoreStlc___-More-on-the-Simply-Typed-Lambda-Calculus--Simple-Extensions-to-STLC--Lists"}});